-- TiDB (MySQL dialect). Ids are UUIDs generated by the app; times are UTC.
-- TiDB only enforces CHECK when tidb_enable_check_constraint is ON, so the app validates too.

CREATE TABLE users (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(80) NOT NULL,
  email VARCHAR(254) NOT NULL,
  password_hash VARCHAR(100) NULL,
  status ENUM('password_pending', 'active') NOT NULL DEFAULT 'password_pending',
  google_sub VARCHAR(64) NULL,
  github_id VARCHAR(32) NULL,
  email_verified_at DATETIME(3) NOT NULL,
  is_demo BOOLEAN NOT NULL DEFAULT FALSE,
  created_at DATETIME(3) NOT NULL,
  UNIQUE KEY users_email_key (email),
  UNIQUE KEY users_google_sub_key (google_sub),
  UNIQUE KEY users_github_id_key (github_id),
  CONSTRAINT users_password_matches_status
    CHECK ((status = 'active') = (password_hash IS NOT NULL))
);

CREATE TABLE sessions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  auth_method ENUM('oauth', 'password') NOT NULL,
  created_at DATETIME(3) NOT NULL,
  last_seen_at DATETIME(3) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  KEY sessions_user_id_idx (user_id),
  KEY sessions_expires_at_idx (expires_at),
  CONSTRAINT sessions_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE rate_limits (
  bucket VARCHAR(160) NOT NULL,
  window_start DATETIME NOT NULL,
  hits INT NOT NULL DEFAULT 1,
  PRIMARY KEY (bucket, window_start),
  KEY rate_limits_window_start_idx (window_start)
);

CREATE TABLE `groups` (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  invite_code VARCHAR(16) NOT NULL,
  created_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  UNIQUE KEY groups_invite_code_key (invite_code),
  KEY groups_created_by_idx (created_by),
  CONSTRAINT groups_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id)
);

CREATE TABLE group_members (
  group_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  role ENUM('admin', 'member') NOT NULL,
  status ENUM('active', 'left') NOT NULL DEFAULT 'active',
  joined_at DATETIME(3) NOT NULL,
  PRIMARY KEY (group_id, user_id),
  KEY group_members_user_id_idx (user_id),
  CONSTRAINT group_members_group_fk FOREIGN KEY (group_id) REFERENCES `groups` (id) ON DELETE CASCADE,
  CONSTRAINT group_members_user_fk FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE expenses (
  id CHAR(36) NOT NULL PRIMARY KEY,
  group_id CHAR(36) NOT NULL,
  paid_by CHAR(36) NOT NULL,
  created_by CHAR(36) NOT NULL,
  amount_centavos INT NOT NULL,
  category ENUM('rent', 'utilities', 'groceries', 'food', 'transport', 'supplies', 'fun', 'other') NOT NULL,
  description VARCHAR(120) NOT NULL,
  split_type ENUM('equal', 'exact', 'percent') NOT NULL,
  spent_on DATE NOT NULL,
  created_at DATETIME(3) NOT NULL,
  KEY expenses_group_spent_on_idx (group_id, spent_on, created_at),
  KEY expenses_paid_by_idx (paid_by),
  KEY expenses_created_by_idx (created_by),
  CONSTRAINT expenses_group_fk FOREIGN KEY (group_id) REFERENCES `groups` (id) ON DELETE CASCADE,
  CONSTRAINT expenses_paid_by_fk FOREIGN KEY (paid_by) REFERENCES users (id),
  CONSTRAINT expenses_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id),
  CONSTRAINT expenses_amount_range CHECK (amount_centavos BETWEEN 1 AND 100000000)
);

CREATE TABLE expense_shares (
  expense_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  share_centavos INT NOT NULL,
  PRIMARY KEY (expense_id, user_id),
  KEY expense_shares_user_id_idx (user_id),
  CONSTRAINT expense_shares_expense_fk FOREIGN KEY (expense_id) REFERENCES expenses (id) ON DELETE CASCADE,
  CONSTRAINT expense_shares_user_fk FOREIGN KEY (user_id) REFERENCES users (id),
  CONSTRAINT expense_shares_not_negative CHECK (share_centavos >= 0)
);

CREATE TABLE settlements (
  id CHAR(36) NOT NULL PRIMARY KEY,
  group_id CHAR(36) NOT NULL,
  from_user CHAR(36) NOT NULL,
  to_user CHAR(36) NOT NULL,
  created_by CHAR(36) NOT NULL,
  amount_centavos INT NOT NULL,
  settled_on DATE NOT NULL,
  created_at DATETIME(3) NOT NULL,
  KEY settlements_group_settled_on_idx (group_id, settled_on, created_at),
  KEY settlements_from_user_idx (from_user),
  KEY settlements_to_user_idx (to_user),
  KEY settlements_created_by_idx (created_by),
  CONSTRAINT settlements_group_fk FOREIGN KEY (group_id) REFERENCES `groups` (id) ON DELETE CASCADE,
  CONSTRAINT settlements_from_user_fk FOREIGN KEY (from_user) REFERENCES users (id),
  CONSTRAINT settlements_to_user_fk FOREIGN KEY (to_user) REFERENCES users (id),
  CONSTRAINT settlements_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id),
  CONSTRAINT settlements_amount_range CHECK (amount_centavos BETWEEN 1 AND 100000000),
  CONSTRAINT settlements_distinct_users CHECK (from_user <> to_user)
);

CREATE TABLE activity_log (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  group_id CHAR(36) NOT NULL,
  actor_id CHAR(36) NOT NULL,
  action ENUM(
    'group_created', 'group_renamed', 'member_joined', 'member_left', 'member_removed',
    'role_changed', 'expense_added', 'expense_edited', 'expense_deleted',
    'settlement_added', 'settlement_deleted'
  ) NOT NULL,
  summary VARCHAR(255) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  KEY activity_log_group_idx (group_id, created_at),
  KEY activity_log_actor_idx (actor_id),
  CONSTRAINT activity_log_group_fk FOREIGN KEY (group_id) REFERENCES `groups` (id) ON DELETE CASCADE,
  CONSTRAINT activity_log_actor_fk FOREIGN KEY (actor_id) REFERENCES users (id)
);

-- Short-lived outbox the WebSocket instances poll. No foreign key, so a "group deleted"
-- event survives the group. Rows older than a day are pruned by the daily cron.
CREATE TABLE group_events (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  group_id CHAR(36) NOT NULL,
  action VARCHAR(32) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  KEY group_events_created_at_idx (created_at)
);
